css:
.scene {
  background: #7B3FC7;
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 40px;
  min-height: 420px;
  overflow: hidden;
  position: relative;
}
.flower-wrap {
  position: relative;
  width: 120px;
  height: 120px;
  margin-bottom: 36px;
}
.orbit-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 110px;
  height: 110px;
  margin: -55px 0 0 -55px;
  border-radius: 50%;
  border: 2px dashed rgba(255,255,255,0.55);
  border-right-color: transparent;
  border-bottom-color: transparent;
  animation: spin 3.5s linear infinite;
}
@keyframes spin {
  from { transform: rotate(-30deg); }
  to   { transform: rotate(330deg); }
}
.orbit-dot {
  position: absolute;
  width: 7px;
  height: 7px;
  background: rgba(255,255,255,0.8);
  border-radius: 50%;
  top: -4px;
  left: 50%;
  margin-left: -3.5px;
}
.flower {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 72px;
  height: 72px;
  margin: -36px 0 0 -36px;
  animation: flowerPulse 4s ease-in-out infinite;
}
@keyframes flowerPulse {
  0%,100% { transform: scale(1) rotate(0deg); }
  50%      { transform: scale(1.08) rotate(15deg); }
}
.petal {
  position: absolute;
  width: 24px;
  height: 34px;
  background: linear-gradient(160deg, #a8c3e8 0%, #7ba6d4 60%, #5a88c0 100%);
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  top: 50%;
  left: 50%;
  transform-origin: 50% 100%;
  margin: -34px 0 0 -12px;
  opacity: 0.92;
}
.center-circle {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 22px;
  height: 22px;
  margin: -11px 0 0 -11px;
  background: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: glow 2.5s ease-in-out infinite;
}
@keyframes glow {
  0%,100% { box-shadow: 0 0 0 3px rgba(255,255,255,0.3); }
  50%      { box-shadow: 0 0 0 6px rgba(255,255,255,0.15); }
}
.center-inner {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 2px solid #8B6ACF;
  background: transparent;
}
.title {
  color: #fff;
  font-size: 22px;
  font-weight: 700;
  text-align: center;
  margin: 0 0 12px;
  letter-spacing: -0.3px;
  animation: fadeUp 1s ease 0.3s both;
  font-family: sans-serif;
}
.subtitle {
  color: rgba(255,255,255,0.78);
  font-size: 14px;
  text-align: center;
  line-height: 1.6;
  max-width: 220px;
  margin: 0;
  animation: fadeUp 1s ease 0.5s both;
  font-family: sans-serif;
}
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0); }
}
.particles {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.p {
  position: absolute;
  border-radius: 50%;
  background: rgba(255,255,255,0.18);
  animation: floatP var(--d) ease-in-out infinite var(--delay);
}
@keyframes floatP {
  0%,100% { transform: translateY(0) scale(1); opacity: 0.18; }
  50%      { transform: translateY(-18px) scale(1.3); opacity: 0.32; }
}
